<?php
namespace Junior; use Junior\Serverside\Request; const ERROR_INVALID_REQUEST = -32600; const ERROR_METHOD_NOT_FOUND = -32601; const ERROR_INVALID_PARAMS = -32602; const ERROR_EXCEPTION = -32099; class Server { public $exposed_instance, $input; public function __construct($exposed_instance) { if (!is_object($exposed_instance)) { throw new Serverside\Exception("Конструктор сервера требует объект"); } $this->exposed_instance = $exposed_instance; $this->input = 'php://input'; } public function methodExists($method_name) { return method_exists($this->exposed_instance, $method_name); } public function invokeMethod($method, $params) { if (is_object($params)) { $array = array(); foreach ($params as $key => $val) { $array[$key] = $val; } $params = array($array); } if ($params === null) { $params = array(); } $reflection = new \ReflectionMethod($this->exposed_instance, $method); if (!$reflection->isPublic()) { throw new Serverside\Exception("Вызываемый метод '{$method}' недоступен публично."); } $num_required_params = $reflection->getNumberOfRequiredParameters(); if ($num_required_params > count($params)) { throw new Serverside\Exception("Передано слишком мало параметров в метод '{$method}'."); } return $reflection->invokeArgs($this->exposed_instance, $params); } public function process() { try { $json = file_get_contents($this->input); } catch (\Exception $e) { throw new Serverside\Exception('Сервер не может прочитать содержимое запроса.', $e->getCode(), $e); } if ($json === false) { throw new Serverside\Exception("Сервер не может прочитать содержимое запроса.", ERROR_EXCEPTION); } $request = $this->makeRequest($json); if (!(defined('ENV') && ENV == 'TEST')) { header('Content-type: application/json'); } if ($request->error_code && $request->error_message) { throw new Serverside\Exception($request->error_message, $request->error_code); } echo $this->handleRequest($request); } public function makeRequest($json) { return new Request($json); } public function handleRequest($request) { if ($request->isBatch()) { $batch = array(); foreach ($request->requests as $req) { $batch[] = $this->handleRequest($req); } $responses = implode(',',array_filter($batch, function($a){return $a !== null;})); if ($responses != null) { return "[{$responses}]"; } else { return null; } } if ($request->checkValid()) { if (!$this->methodExists($request->method)) { $request->error_code = ERROR_METHOD_NOT_FOUND; $request->error_message = "Метод '{$request->method}' не найден."; return $request->toResponseJSON(); } try { $response = $this->invokeMethod($request->method, $request->params); if (!$request->isNotify()) { $request->result = $response; } else { return null; } } catch (\Exception $e) { $request->error_code = $e->getCode() ?: ERROR_EXCEPTION; $request->error_message = $e->getMessage(); $request->exception = $e; } } return $request->toResponseJSON(); } } 